package by.bsuir.payment;
import by.bsuir.repair.contract.*; import by.bsuir.repair.runtime.*; import io.grpc.*; import io.grpc.stub.StreamObserver; import jakarta.annotation.PreDestroy; import org.springframework.beans.factory.annotation.Value; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.time.*; import java.util.*; import java.util.concurrent.TimeUnit;
@Service public class PaymentGrpcService extends PaymentServiceGrpc.PaymentServiceImplBase {
 private final JdbcTemplate jdbc; private final Jsons jsons; private final OutboxService outbox; private final ManagedChannel channel; private final WorkOrderServiceGrpc.WorkOrderServiceBlockingStub workOrders;
 public PaymentGrpcService(JdbcTemplate jdbc,Jsons jsons,OutboxService outbox,@Value("${integration.work-order.host:localhost}")String host,@Value("${integration.work-order.port:9104}")int port){this.jdbc=jdbc;this.jsons=jsons;this.outbox=outbox;channel=ManagedChannelBuilder.forAddress(host,port).usePlaintext().intercept(GrpcCorrelation.client()).build();workOrders=WorkOrderServiceGrpc.newBlockingStub(channel);}
 @PreDestroy void close(){channel.shutdown();}
 @Override public void listPayments(JsonMessage req,StreamObserver<JsonMessage> obs){try{var in=jsons.read(req);UUID order=UUID.fromString(jsons.string(in,"workOrderId"));var rows=jdbc.queryForList("select id,work_order_id AS \"workOrderId\",client_id AS \"clientId\",amount,method,status,provider_payment_id AS \"providerPaymentId\",paid_at AS \"paidAt\",created_at AS \"createdAt\" from payments where work_order_id=? order by created_at",order);if("CLIENT".equals(Objects.toString(in.get("role")))&&rows.stream().anyMatch(x->!x.get("clientId").toString().equals(Objects.toString(in.get("currentUserId")))))throw new SecurityException("Client can access only own payments");jsons.reply(obs,rows);}catch(Throwable e){jsons.fail(obs,e);}}
 @Override @Transactional public void registerPayment(JsonMessage req,StreamObserver<JsonMessage> obs){try{var in=jsons.read(req);UUID order=UUID.fromString(jsons.string(in,"workOrderId")),current=UUID.fromString(jsons.string(in,"currentUserId"));String key=DomainRules.idempotencyKey(jsons.string(in,"idempotencyKey"));var existing=jdbc.queryForList("select id from payments where idempotency_key=?",key);if(!existing.isEmpty()){jsons.reply(obs,find((UUID)existing.get(0).get("id")));return;}var summary=jsons.read(workOrders.withDeadlineAfter(1500,TimeUnit.MILLISECONDS).getSummary(jsons.write(Map.of("id",order))).getJson());UUID client=UUID.fromString(summary.get("clientId").toString());if("CLIENT".equals(jsons.string(in,"role"))&&!client.equals(current))throw new SecurityException("Work order belongs to another client");if(!Boolean.TRUE.equals(summary.get("payable")))throw Status.FAILED_PRECONDITION.withDescription("Work order is not payable").asRuntimeException();BigDecimal amount=new BigDecimal(summary.get("totalAmount").toString());if(amount.signum()<=0)throw Status.FAILED_PRECONDITION.withDescription("Payment amount must be positive").asRuntimeException();String method=Objects.toString(in.getOrDefault("method","CARD"));String status=method.equals("FAIL_TEST")?"FAILED":"COMPLETED";UUID id=UUID.randomUUID();var now=java.time.OffsetDateTime.now(java.time.ZoneOffset.UTC);String provider="LOCAL-"+UUID.randomUUID();jdbc.update("insert into payments(id,work_order_id,client_id,amount,method,status,provider_payment_id,idempotency_key,paid_at,created_at) values(?,?,?,?,?,?,?,?,?,?)",id,order,client,amount,method,status,provider,key,status.equals("COMPLETED")?now:null,now);var value=find(id);outbox.enqueue(EventTopics.PAYMENT,status.equals("COMPLETED")?"PaymentCompleted":"PaymentFailed",id,value);jsons.reply(obs,value);}catch(Throwable e){jsons.fail(obs,e);}}
 @Override public void getPaymentStatus(JsonMessage req,StreamObserver<JsonMessage> obs){try{jsons.reply(obs,find(UUID.fromString(jsons.string(jsons.read(req),"id"))));}catch(Throwable e){jsons.fail(obs,e);}}
 private Map<String,Object> find(UUID id){var rows=jdbc.queryForList("select id,work_order_id AS \"workOrderId\",client_id AS \"clientId\",amount,method,status,provider_payment_id AS \"providerPaymentId\",paid_at AS \"paidAt\",created_at AS \"createdAt\" from payments where id=?",id);if(rows.isEmpty())throw Status.NOT_FOUND.withDescription("Payment not found").asRuntimeException();return rows.get(0);}
}



